function validate([sentence1, sentence2]) {
  for (const s of [sentence1, sentence2]) {
    if (typeof s !== 'string' || s.length < 1 || s.length > 100) return 'Each sentence needs 1 to 100 characters.';
    if (!/^[A-Za-z]+( [A-Za-z]+)*$/.test(s)) return 'A sentence is letter-only words separated by single spaces, with no space at either end.';
  }
  return null;
}

