function areSentencesSimilar(sentence1, sentence2) {
  let shorter = sentence1.split(' ');
  let longer = sentence2.split(' ');
  if (shorter.length > longer.length) {
    [shorter, longer] = [longer, shorter];
  }
  const gap = longer.length - shorter.length;
  let left = 0;
  let right = shorter.length - 1;

  while (left <= right && shorter[left] === longer[left]) {
    left++;
  }
  while (left <= right && shorter[right] === longer[right + gap]) {
    right--;
  }
  return left > right;
}

