function areSentencesSimilar(sentence1, sentence2) {
  const a = sentence1.split(' ');
  const b = sentence2.split(' ');
  const growsInto = (small, big) => {
    for (let i = 0; i <= big.length; i++) {
      for (let j = i; j <= big.length; j++) {
        const rest = big.slice(0, i).concat(big.slice(j));
        if (rest.join(' ') === small.join(' ')) return true;
      }
    }
    return false;
  };
  return growsInto(a, b) || growsInto(b, a);
}

