function generate(rand, size) {
  const vocab = rand() < 0.5 ? ['a', 'b', 'A', 'ab'] : ['a', 'b', 'c', 'Ab', 'ba', 'xyz', 'Hi'];
  const word = () => vocab[Math.floor(rand() * vocab.length)];
  const sentenceOf = (words) => words.join(' ');
  const maxWords = size === 'large' ? 40 : 6;
  for (;;) {
    const longCount = 1 + Math.floor(rand() * maxWords);
    const longer = Array.from({ length: longCount }, word);
    let shorter;
    const mode = rand();
    if (mode < 0.6) {
      const keep = 1 + Math.floor(rand() * longCount);
      const front = Math.floor(rand() * (keep + 1));
      shorter = longer.slice(0, front).concat(longer.slice(longCount - (keep - front)));
      if (rand() < 0.3) shorter[Math.floor(rand() * shorter.length)] = word();
    } else {
      shorter = Array.from({ length: 1 + Math.floor(rand() * longCount) }, word);
    }
    const s1 = sentenceOf(shorter);
    const s2 = sentenceOf(longer);
    if (s1.length > 100 || s2.length > 100) continue;
    return rand() < 0.5 ? [s1, s2] : [s2, s1];
  }
}
